import { createSlotSymbolCatalog, type SlotGameDefinition, type SlotSymbolDefinition } from '../0000/SGEngine/Domain/SlotGameDefinition';

const MULTIPLIER_VALUES = [2, 3, 4, 6, 8, 10, 12, 15, 18, 25, 50, 55, 60, 65, 80, 100, 150, 200, 250, 500] as const;

const NORMAL_SYMBOLS = [
    { id: 1, kind: 'normal', name: 'sym1', frame: 'symbol_h1' },
    { id: 2, kind: 'normal', name: 'sym2', frame: 'symbol_h2' },
    { id: 3, kind: 'normal', name: 'sym3', frame: 'symbol_h3' },
    { id: 4, kind: 'normal', name: 'sym4', frame: 'symbol_h4' },
    { id: 5, kind: 'normal', name: 'sym5', frame: 'symbol_l1' },
    { id: 6, kind: 'normal', name: 'sym6', frame: 'symbol_l2' },
    { id: 7, kind: 'normal', name: 'sym7', frame: 'symbol_l3' },
    { id: 8, kind: 'normal', name: 'sym8', frame: 'symbol_l4' },
    { id: 9, kind: 'normal', name: 'sym9', frame: 'symbol_l5' },
] satisfies readonly SlotSymbolDefinition[];

const SCATTER_SYMBOL = { id: 10, kind: 'scatter', name: 'scatter', frame: 'symbol_scatter' } satisfies SlotSymbolDefinition;
const JACKPOT_SYMBOL = { id: 1000, kind: 'jackpot', name: 'jackpot', frame: 'symbol_jackpot' } satisfies SlotSymbolDefinition;

const multiplierSymbols = (startId: number, upgradeable: boolean): SlotSymbolDefinition[] =>
    MULTIPLIER_VALUES.map((value, index) => ({
        id: startId + index,
        kind: 'multiplier',
        name: `mul${value}`,
        value,
        upgradeable,
        colorTier: 4 - Math.floor(index / 5),
        frame: ({ side, symbol }) => `symbol_m${side}_${symbol.colorTier}`,
    }));
export const SLOT_GAME_DEFINITION: SlotGameDefinition = {
    symbols: createSlotSymbolCatalog({
        symbols: [...NORMAL_SYMBOLS, SCATTER_SYMBOL, ...multiplierSymbols(11, false), ...multiplierSymbols(111, true), JACKPOT_SYMBOL],
        fallback: { kind: 'normal', name: 'unknown', frame: 'symbol_h1' },
    }),
};
