import { BitmapFont, Button, Label, Node, UITransform, instantiate } from 'cc';
import { HistoryAdapter as HistoryAdapterBase } from '../../../0000/SGEngine/View/History/HistoryAdapter';
import type { BetHistoryDetail } from '../../../0000/SGEngine/Domain/BetHistory';
import type { SlotRoundStep } from '../../../0000/SGEngine/Domain/SlotRound';
import AppAssetBundle from '../../../../base/utility/AppAssetBundle';
import GameConfigManager from '../../../0000/Core/Runtime/GameConfigManager';
import { GAMEVIEWMAP } from '../../../0000/Core/Runtime/Store/StoreMap';
import { SLOT_GAME_DEFINITION } from '../../SlotGameDefinition';

export default class HistoryAdapter extends HistoryAdapterBase {
    protected readonly symbolsFolder = 'Images/symbols';
    protected readonly symbolCatalog = SLOT_GAME_DEFINITION.symbols;

    private static readonly MULTIPLIER_FONT_PATH = 'font/MU/num_mu';
    private static readonly MULTIPLIER_LABEL_FONT_SIZE = 36;

    private multiplierFont: BitmapFont | null = null;
    private historyRoundUnits: Node[] = [];
    private historyRoundIndex = 0;

    protected override resolveMulti(symbolId: number): string | undefined {
        const info = this.symbolCatalog.resolve(symbolId);
        return info.kind === 'multiplier' ? `${info.value}x` : undefined; // 6x
    }

    override async getRoundDetail(data: BetHistoryDetail, isPortrait: boolean = false): Promise<Node> {
        const prefab = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadPrefab(GAMEVIEWMAP.HISTORYROUNDDETAIL.path);
        const root = instantiate(prefab) as Node;
        const portraitWidth = 700;
        const setWidth = (unit: Node) => {
            if (!isPortrait) return;
            const ut = unit.getComponent(UITransform);
            if (ut) ut.width = portraitWidth;
        };

        const rounds = this.getMainHistoryRounds(data);
        const units = await Promise.all(rounds.map((round) => this.createNormalUnit(round.grid)));

        units.forEach((unit, index) => {
            setWidth(unit);
            this.setUnitWin(unit, data.summary.currency, rounds[index].win);
            this.bindHistoryRoundButtons(unit);
            this.updateHistoryRoundButtons(unit, index, units.length);
            unit.active = index === 0;
            root.addChild(unit);
        });

        this.historyRoundUnits = units;
        this.historyRoundIndex = 0;

        return root;
    }

    /** NG遊戲盤面 */
    private getMainHistoryRounds(data: BetHistoryDetail): readonly SlotRoundStep[] {
        return data.mainSteps;
    }

    /** FG遊戲盤面 確定後再接入 */
    private getFreeHistoryRounds(data: BetHistoryDetail): readonly (readonly SlotRoundStep[])[] {
        return data.freeRounds;
    }

    /** 上一盤 */
    public showPreviousHistoryRound(): void {
        this.showHistoryRound(this.historyRoundIndex - 1);
    }

    /** 下一盤 */
    public showNextHistoryRound(): void {
        this.showHistoryRound(this.historyRoundIndex + 1);
    }

    private bindHistoryRoundButtons(unit: Node): void {
        const table = unit.getChildByName('Table');
        const previousButton = table?.getChildByName('PreviousButton');
        const nextButton = table?.getChildByName('NextButton');

        previousButton?.on(Button.EventType.CLICK, this.showPreviousHistoryRound, this);
        nextButton?.on(Button.EventType.CLICK, this.showNextHistoryRound, this);
    }

    private showHistoryRound(index: number): void {
        const total = this.historyRoundUnits.length;
        if (total === 0) return;

        this.historyRoundIndex = Math.min(Math.max(index, 0), total - 1);
        this.historyRoundUnits.forEach((unit, unitIndex) => {
            unit.active = unitIndex === this.historyRoundIndex;
            this.updateHistoryRoundButtons(unit, unitIndex, total);
        });
    }

    private updateHistoryRoundButtons(unit: Node, index: number, total: number): void {
        const table = unit.getChildByName('Table');
        const previousButton = table?.getChildByName('PreviousButton');
        const nextButton = table?.getChildByName('NextButton');

        if (previousButton) previousButton.active = index > 0;
        if (nextButton) nextButton.active = index < total - 1;
    }

    private async getMultiplierFont(): Promise<BitmapFont | null> {
        if (this.multiplierFont) return this.multiplierFont;
        const bundle = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).getBundle();
        return new Promise((resolve) => {
            bundle.load(HistoryAdapter.MULTIPLIER_FONT_PATH, BitmapFont, (err, asset) => {
                if (err) {
                    console.warn(`[HistoryAdapter] load font failed: ${HistoryAdapter.MULTIPLIER_FONT_PATH}`, err);
                    resolve(null);
                    return;
                }
                this.multiplierFont = asset as BitmapFont;
                resolve(this.multiplierFont);
            });
        });
    }

    /** 沒有prefab 容器會直接清空 label直接疊上去 */
    protected override async renderMultiplierLabel(posNode: Node, multi: string): Promise<void> {
        const font = await this.getMultiplierFont();

        const labelNode = new Node('MultiplierLabel');
        labelNode.addComponent(UITransform);
        const label = labelNode.addComponent(Label);
        label.string = multi;
        label.fontSize = HistoryAdapter.MULTIPLIER_LABEL_FONT_SIZE;
        label.horizontalAlign = Label.HorizontalAlign.CENTER;
        label.verticalAlign = Label.VerticalAlign.CENTER;
        if (font) {
            label.useSystemFont = false;
            label.font = font;
        }
        posNode.addChild(labelNode);
    }
}
